package org.firstinspires.ftc.teamcode.hardware.subsystems;

import com.qualcomm.robotcore.hardware.DcMotorSimple;
import com.qualcomm.robotcore.hardware.HardwareMap;
import com.qualcomm.robotcore.hardware.Servo;

import org.firstinspires.ftc.teamcode.config.PollenPusherConstants;

public class PollenPusher {
    private PollenPusherConstants constants;
    private Servo actuator;

    public PollenPusher(HardwareMap hardwareMap) {
        this.constants = new PollenPusherConstants();
        this.actuator = hardwareMap.get(Servo.class, constants.getActuatorLabel());
        actuator.setDirection(constants.getActuatorDirection() == DcMotorSimple.Direction.FORWARD ? Servo.Direction.FORWARD : Servo.Direction.REVERSE);
    }

    public void setPosition(double position) {
        actuator.setPosition(position);
    }

    public void extend() {
        setPosition(constants.getExtendPosition());
    }

    public void retract() {
        setPosition(constants.getRetractPosition());
    }

    public void stop() {
        // Positional servos hold their last position.
    }
}

package org.firstinspires.ftc.teamcode.config;

import com.qualcomm.robotcore.hardware.DcMotor;
import com.qualcomm.robotcore.hardware.DcMotorSimple;

public class ShooterConstants {
    private String actuatorLabel = "shooter actuator";
    private DcMotorSimple.Direction actuatorDirection = DcMotorSimple.Direction.FORWARD;
    private DcMotor.ZeroPowerBehavior actuatorZeroPowerBehavior = DcMotor.ZeroPowerBehavior.FLOAT;
    private double targetVelocity = 1500.0;
    private double velocityTolerance = 50.0;

    public String getActuatorLabel() {
        return actuatorLabel;
    }

    public DcMotorSimple.Direction getActuatorDirection() {
        return actuatorDirection;
    }

    public DcMotor.ZeroPowerBehavior getActuatorZeroPowerBehavior() {
        return actuatorZeroPowerBehavior;
    }

    public double getTargetVelocity() {
        return targetVelocity;
    }

    public double getVelocityTolerance() {
        return velocityTolerance;
    }
}

package org.firstinspires.ftc.teamcode.hardware.subsystems;

import com.qualcomm.robotcore.hardware.DcMotor;
import com.qualcomm.robotcore.hardware.DcMotorEx;
import com.qualcomm.robotcore.hardware.HardwareMap;

import org.firstinspires.ftc.teamcode.config.ShooterConstants;

public class Shooter {
    private ShooterConstants constants;
    private DcMotorEx actuator;

    public Shooter(HardwareMap hardwareMap) {
        this.constants = new ShooterConstants();
        this.actuator = hardwareMap.get(DcMotorEx.class, constants.getActuatorLabel());
        actuator.setDirection(constants.getActuatorDirection());
        actuator.setZeroPowerBehavior(constants.getActuatorZeroPowerBehavior());
        actuator.setMode(DcMotor.RunMode.RUN_USING_ENCODER);
    }

    public void setVelocity(double ticksPerSecond) {
        actuator.setVelocity(ticksPerSecond);
    }

    public void spinUp() {
        setVelocity(constants.getTargetVelocity());
    }

    public boolean isAtSpeed() {
        return Math.abs(actuator.getVelocity() - constants.getTargetVelocity()) <= constants.getVelocityTolerance();
    }

    public double getVelocity() {
        return actuator.getVelocity();
    }

    public void stop() {
        actuator.setPower(0);
    }
}

package org.firstinspires.ftc.teamcode.robots;

import com.qualcomm.robotcore.hardware.HardwareMap;

import org.firstinspires.ftc.teamcode.hardware.subsystems.Drivetrain;
import org.firstinspires.ftc.teamcode.hardware.subsystems.Intake;
import org.firstinspires.ftc.teamcode.hardware.subsystems.Feeder;
import org.firstinspires.ftc.teamcode.hardware.subsystems.PollenPusher;
import org.firstinspires.ftc.teamcode.hardware.subsystems.Shooter;

public class Robot {
    private Drivetrain drivetrain;
    private Intake intake;
    private Feeder feeder;
    private PollenPusher pollenPusher;
    private Shooter shooter;

    public Robot(HardwareMap hardwareMap) {
        this.drivetrain = new Drivetrain(hardwareMap);
        this.intake = new Intake(hardwareMap);
        this.feeder = new Feeder(hardwareMap);
        this.pollenPusher = new PollenPusher(hardwareMap);
        this.shooter = new Shooter(hardwareMap);
    }

    public Drivetrain getDrivetrain() {
        return drivetrain;
    }

    public Intake getIntake() {
        return intake;
    }

    public Feeder getFeeder() {
        return feeder;
    }

    public PollenPusher getPollenPusher() {
        return pollenPusher;
    }

    public Shooter getShooter() {
        return shooter;
    }

    public void stop() {
        drivetrain.stop();
        intake.stop();
        feeder.stop();
        pollenPusher.stop();
        shooter.stop();
    }
}

